#!/usr/bin/env bash
# @generated by @metaobjectsdev/pack-cloudflare (cloudflare-sync-secrets) — hand edits are kept by a three-way merge on regeneration; meta verify --codegen checks only the generated parts.
# Copies every secret setting app.client acme::help::Help.site reads from the vault to the Pages project's environment,
# for one environment: production when its branch is the project's production branch, else preview.
# A value goes from keys-axi's environment through a pipe into `wrangler pages secret put`:
# it is never printed and never on a command line.
#
# Needs: keys-axi (an identity that may read the vault scope) and what deploy/cloudflare/wrangler.sh needs.
#
#   bash deploy/cloudflare/sync-secrets.sh <environment> [--dry-run]
set -euo pipefail
cd "$(dirname "$0")/../.."

ENVIRONMENT="${1:-}"
DRY_RUN=0
for arg in "${@:2}"; do
  case "$arg" in
    --dry-run) DRY_RUN=1 ;;
    *) echo 'usage: bash deploy/cloudflare/sync-secrets.sh <environment> [--dry-run]' >&2; exit 2 ;;
  esac
done
KEYS_AXI="${KEYS_AXI:-$(command -v keys-axi || echo "$HOME/.local/bin/keys-axi")}"

# copy <vault project> <vault environment> <NAME> <Pages project> <Pages environment>
copy() {
  if [ "$DRY_RUN" = 1 ]; then echo "would copy $3 from $1/$2 to Pages project $4, $5 environment ($ENVIRONMENT)"; return; fi
  # shellcheck disable=SC2016 # the inner shell expands it: the value never enters this one
  "$KEYS_AXI" run --project "$1" --env "$2" --only "$3" -- bash -c '
    [ -n "${!1+set}" ] || { echo "sync-secrets: $1 is not in the vault scope" >&2; exit 1; }
    value="${!1}"
    unset "$1"
    printf %s "$value" | bash deploy/cloudflare/wrangler.sh "$2" pages secret put "$1" --project-name "$3" --env "$4" >/dev/null
  ' sync-secret "$3" "$ENVIRONMENT" "$4" "$5"
  echo "copied $3 to Pages project $4, $5 environment ($ENVIRONMENT)"
}

case "$ENVIRONMENT" in
  production)
    copy acme-help prod SEARCH_API_KEY help-site production
    ;;
  preview)
    copy acme-help-preview preview SEARCH_API_KEY help-site preview
    ;;
  *) echo 'usage: bash deploy/cloudflare/sync-secrets.sh <environment> [--dry-run] (environments: production, preview)' >&2; exit 2 ;;
esac
